-- Stories Library redesign: 6 stories x 12 sentences each, replacing the
-- previous 2 stories x 24 sentences. Distributed across all 3 levels
-- (2 per level) so the new library's three level filters each have real
-- content. Normal-mode and Conversation content are untouched.
--
-- Generated from the same TypeScript source the app reads locally
-- (src/data/lessons/stories.ts) by a one-off script mirroring
-- scripts/generate-content-seed.ts's approach.
--
-- No order_index collision risk here (unlike the earlier normal-mode
-- migration): story-1 keeps order_index 1, story-2 moves from 2 to 3
-- (currently unoccupied, since only 2 stories exist today), and the 4
-- new stories take order_index 2, 4, 5, 6 -- none of which any existing
-- row currently holds. Wrapped in a transaction regardless, so a failure
-- rolls back cleanly instead of leaving a half-migrated state.
begin;

-- Lessons: full replacement of the stories-mode library

-- Sentences

-- Cleanup: story-1 and story-2 previously had 24 sentences (order_index 0-23); remove the now-stale trailing twelve.
delete from sentences where lesson_id in ('story-1', 'story-2') and order_index >= 12;

commit;
